package com.ruoyi.web.controller.monitor;
import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.springframework.stereotype.Component;import jakarta.servlet.http.HttpServletResponse;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import com.ruoyi.framework.audit.LogQueryService;import com.ruoyi.common.utils.SecurityUtils;import com.ruoyi.common.exception.ServiceException;
@Component public class AuditExport {
 private final LogQueryService service;private final Map<Long,Long> last=new ConcurrentHashMap<>();public AuditExport(LogQueryService s){service=s;}
 public void write(String kind,Map<String,String> p,HttpServletResponse response)throws Exception{long user=SecurityUtils.getUserId(),now=System.currentTimeMillis();synchronized(last){if(now-last.getOrDefault(user,0L)<60000)throw new ServiceException("每分钟仅允许导出一次");last.put(user,now);}var rows=(List<Map<String,Object>>)service.list(kind,p,true).get("rows");try(var book=new XSSFWorkbook()){var sheet=book.createSheet("日志");if(!rows.isEmpty()){var keys=new ArrayList<>(rows.get(0).keySet());var header=sheet.createRow(0);for(int i=0;i<keys.size();i++)header.createCell(i).setCellValue(keys.get(i));for(int n=0;n<rows.size();n++){var row=sheet.createRow(n+1);for(int i=0;i<keys.size();i++)row.createCell(i).setCellValue(String.valueOf(rows.get(n).getOrDefault(keys.get(i),"")));}for(int i=0;i<keys.size();i++)sheet.setColumnWidth(i,6000);}response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");response.setHeader("Content-Disposition","attachment; filename=audit-"+kind+".xlsx");book.write(response.getOutputStream());}}
}
